package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSoDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Ka-hortagga dhammaan waxyeelada", "Magaca Eebe yaan ku Billaabaynaa ee aan Magaciisa waxba ku dhibin Dhulka iyo Samada midna, Eebana waa maqle oge ah.", "Saddex jeer subax kasta iyo galab kasta.", "Ku alla kii saddex jeer ku hadla subax iyo galabba waxba isaga yeeli maayo."),
        "dua_raditu_billahi" to DuaText("Ku Qanacsanaanta Allaah Rabbi ahaan", "Waxaan ku raalli noqday Eebbe Rabbigiis, Islaamkana diinteyda iyo Muxammad ﷺ inuu yahay nabigeyga.", "Saddex jeer subax iyo galabba.", "Waxay noqonaysaa xaq Eebbe korkiisa ahaa inuu ka raalli geliyo maalinta qiyaame."),
        "dua_hasbiyallah" to DuaText("Xasbiyallah (Alle waa ku filan yahay)", "Alle ayaa igu filan; Ilaah kale ma jiro isaga mooyee. Isagaan tala saarta, isagaana ah Eebaha Carshiga wayn.", "Toddoba jeer subax iyo galabba.", "Aayad Quraan ah; Alle ayaa ku filan welwelka adduun iyo aakhiro."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubxaanAllahi wa bihamdihi", "Subxaanallaah, mahad oo dhan isagaa iska leh.", "Boqol jeer maalintii.", "Ku alla kii yidhaahda boqol jeer maalintii dembigiisa waa cafiyan yihiin, xataa hadday yihiin sida xumbo badda."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Ma jiro cid xaq u leh in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin. Xukunka isagaa iska leh mahadna isagaa iska leh, wax walbana wuu karaa.", "Wanaag weyn oo lagu sheego boqol jeer maalintii.", "Abaalmarinta Toban Addoon oo la xoreeyo, boqol camal oo wanaagsan oo qoran, boqol dembi oo la tirtiro, Sheydaankana laga ilaaliyo ilaa maqribka."),
        "dua_leaving_mosque" to DuaText("Ka bixida Masjidka", "Allahayow waxaan ku waydiisanayaa fadligaada.", "Marka laga soo baxayo masjidka lugta bidix.", "In la waydiiyo fadliga iyo risqiga Alle marka laga baxayo masaajidka."),
        "dua_after_adhan" to DuaText("Adhan ka dib", "Allahayow baaqan kaamil ah iyo ducada la dhisi doono, sii Muxammad ﷺ al-Wasiilah iyo fadligiisa, oo kor u qaad maqaamkii aad u ballan qaaday.", "Kadib marka ay dhamaato adhan.", "Qofkii sidaas yiraahda waxaa la siin doonaa shafeecada Nabiga ﷺ maalinta qiyaame."),
        "dua_after_salah_istighfar" to DuaText("Fard Saalax ka dib", "Waxaan danbi dhaaf waydiisanayaa Alle (3 jeer). Allow adigaa salaam oo agtaada nabadi. Waad ku mahadsantahay, adaa leh sharafta iyo karaamada.", "Isla markiiba salaan ka dib.", "Nabiga ﷺ wuxuu akhriyay tan salaad kasta oo waajib ah ka dib."),
        "dua_after_salah_help_dhikr" to DuaText("Iga caawi in aan ku xasuusto", "Allow igu kaalmee inaan ku xuso, inaan ku mahadiyo oo aan kugu caabudo sida ugu wanaagsan.", "Salaad kasta ka dib - Nabigu ﷺ wuxuu kula taliyay Mucaad (RA) inuu sheego.", "Talo gaar ah oo Nabiga ﷺ - heer sare iyo joogtaynta cibaadada."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Faatimi hurdada ka hor", "Subxaanallaah (33), Mahad oo dhan Allaah ayaa iska leh (33), Allaah ayaa weyn (34).", "Hurdada ka hor - Nabigu ﷺ baray Faaduma iyo Cali (RA).", "Nabigu ﷺ wuxuu yidhi adigaa kuu roon adoo addoon ah."),
        "dua_sleep_qina_adhab" to DuaText("Ka ilaalinta ciqaabta", "Allahayow cadaabkaga iga ilaali maalinta aad soo bixinayso adoomadaada.", "Saddex jeer, iyadoo gacanta midig la dhigay dhabanka hoostiisa.", "Waxay hurdadu u beddeshaa xusuus geerida iyo u diyaargarowga aakhiro."),
        "dua_bad_dream" to DuaText("Riyo Xun Kadib", "Illahay baan ka magan galay shaydaanka la nacladay.", "Riyo xun ka dib: si khafiif ah ugu tufi bidix saddex jeer, ka dibna u leexo dhinaca kale.", "Riyada xun waxba kuma yeeli doonto; cidna ha u sheegin."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "Allow noolow, arsaaqeeye. Naxariistaada ayaan gargaar ku doonaye.", "Marka arrintu noqoto mid aad u culus.", "Mar kasta oo ay wax dhibaan nebiga ﷺ, wuxuu odhan jiray sidan."),
        "dua_entering_market" to DuaText("Gelida Suuqa", "Ma jiro cid xaq u leh in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin. Xukunka isagaa iska leh, Mahadna isagaa leh. Isagaa wax nooleeya waxna dila, Eebana waa noole ma dhiman. Wanaag oo dhammi gacantiisay ku jiraan, wax walbana wuu karaa.", "Marka la soo galo suuqa.", "Xadiisku wuxuu sheegay in ajar weyn laga helayo (hal milyan oo camal wanaagsan ah)."),
        "dua_adam_forgiveness" to DuaText("Ducadii Nabi Aadam (AS)", "Eebow waan dulminay nafteena, haddaadan noo dambi dhaafin oodan noo naxariisan waxaan noqonaynaa kuwa khasaaray.", "Ducadii tawbada Aadan iyo Xaawo (AS).", "Towbada ugu horraysa ee bani-aadmiga - Alle wuu aqbalay."),
        "dua_abu_bakr" to DuaText("Ducadii la baray Abuu Bakar (RA)", "Illahow waxaan dulmi weyn u geystay naftayda, wax dambi dhaafana ma jiro adiga mooyee, ee ii dambi dhaaf naftaada oo ii naxariiso. illeen waxaad tahay dambi dhaafe Naxariista.", "Nebigu ﷺ waxa uu baray Abu Bakar as-Siddiiq (RA) in uu salaadda ku tukado (tashahud ka dib).", "Ducada sunnada ah ee salaadda dhammaatay."),
        "dua_astaghfirullah_atubu" to DuaText("Istighfaarka maalinlaha ah", "Allaah ayaan danbi dhaaf waydiisanayaa isagana waan u toobad keenayaa.", "Nebigu ﷺ waxa uu dalbaday in ka badan todobaatan jeer maalintii.", "Nebigu ﷺ wuxuu yidhi: Waxaan ka warsadaa dambi dhaaf Alle oo aan u toobad keeno in ka badan todobaatan jeer maalintii."),
        "dua_laylatul_qadr" to DuaText("Ducada Laylatul Qadriga", "Allahayow adaa danbi dhaaf ah waxaadna jeceshahay cafiska ee i cafi.", "Waxaa la baray Caa'isha (RA) ee Laylatul Qadr.", "Duco gaar ah oo loogu talagalay habeennada ugu dambeeya Ramadaan iyo Laylatul-Qadriga."),
        "dua_family_coolness" to DuaText("Qabow ee Indhaha (Xaaska & Carruurta)", "Eebow naga yeel xaaskayaga iyo faracyadanada qabowga indhahayaga, naga yeel kuwa suuban.", "Ducada quraanka ee xaaska iyo caruurta xaqa ah.", "Nabadda guriga iyo carruurta xaqa ah."),
        "dua_righteous_children" to DuaText("Farcan Xaqa ah", "Eebow iga sii agtaada farac daahir ah. illeen adaa maqle baryada.", "Ducadii Nabi Zakariya (AS).", "Duco Qur'aanka Kariimka ah oo loogu talagalay kuwa doonaya caruur."),
        "dua_ibrahim_prayer_family" to DuaText("Aasaasayaasha Salaadda", "Eebow iga yeel mid ooga salaadda iyo farcankayga. Rabbiyow, baryadayda aqbal. Eebow u dambi dhaaf aniga iyo waalidkay iyo kuwa rumeeyey maalinta xisaabtu la kiciyo.", "Ducadii Nabi Ibraahiim (AS) isaga iyo tafiirtiisaba.", "Si caadi ah loo akhriyo dhamaadka salaadda."),
        "dua_newlywed" to DuaText("Hambalyo lamaanaha cusub", "Allaah ha idin barakeeyo, barako ha idiin soo daayo, labadiinaba wanaag ha idin waafajiyo.", "Marka qof loogu hambalyeeyo guurkiisa.", "Hambalyada sunnada ee guurka."),
        "dua_before_eating" to DuaText("Kahor Cunista", "Magaca Allaah. (Haddii la ilaawo:) Magaca Eebe yaan ku Billaabaynaa, Bilowgii iyo Aakhirkiiba.", "Ka hor inta aanad cunin. Haddii aad illowdo, u sheeg qayb ahaan.", "Bismillah oo la dhaho waxay shaydaanka ka ilaalinaysaa in uu cuntada la qaybsado."),
        "dua_after_eating" to DuaText("Cunista ka dib", "Mahad dhamaanteed waxay u sugnaatay Allahii i quudiyay oo igu arzuqeeyay anoon quwad iyo tabar toona lahayn", "Ka dib markaad dhammayso cuntada.", "Dembiyadii hore kii yiraahda waa la dhaafaa."),
        "dua_host" to DuaText("Ee Martigaliyaha", "Allahayow ku barako waxaad ku arsaaqday, una dambi dhaaf una naxariiso.", "Qofka martida loo yahay, ka dib marka uu qof gurigiisa wax ka cuno.", "U mahadcelinta martigaliyaha habka sunnada ah."),
        "dua_breaking_fast" to DuaText("Marka la Afurayo", "Haraadkii baa baxay, xididdada ayaa qoyay, ajarkiina waa la sugay, haddii Eebbe idmo.", "Xiliga afurka.", "Nabigu ﷺ waxa uu sidaa yidhi mar uu afuray."),
        "dua_new_clothes" to DuaText("Xidhashada Dhar Cusub", "Alloow mahad oo dhan adigaa iska leh; Waxaad i huwisay tan. Waxaan ku waydiisanayaa wanaageeda iyo wanaageeda waxa loo sameeyay, waxaana kaa magan galay xumaanteeda iyo xumaanteeda.", "Markaad xidhato maro cusub (magacaabid, sida shaadh ama cimaamad).", "Nebigu ﷺ ayaa ducadan sameeyay markuu maro cusub xidho. (Ducada maalinlaha ah ee labiska waxay ku hoos jirtaa 'Labbiska'.)"),
        "dua_rabbana_atina" to DuaText("Wanaag Adduun iyo Aakhiro", "Eebow na sii adduunyo wanaag, aakhirona wanaag, naga ilaali cadaabka naarta.", "Ducadii Nebigu ﷺ sameeyay inta badan.", "Duco kulmisa wanaag kasta oo adduun iyo aakhiro."),
        "dua_rabbi_zidni_ilma" to DuaText("Kordhinta Aqoonta", "Eebow ii siyaadi cilmiga.", "Si loo kordhiyo aqoonta.", "Eebe wuxuu Nabiga ﷺ ku amray in loo kordhiyo wax aan cilmi ahayn."),
        "dua_musa_sharh_sadr" to DuaText("Furitaanka Xabadka (Muuse AS)", "Eebow laabta ii waasici, hawshaydana ii fududee, carrabkaygana xadhigga ka fur si ay hadalkayga u fahmaan.", "Imtixaan ka hor, hadal ama hawl kasta oo adag.", "Ducadii Nabi Muuse (AS) - Dejinta qalbiga iyo fudaydka shaqada."),
        "dua_la_tuzigh" to DuaText("Adkeysiga Qalbiga", "Eebow yeyna iilin quluubtayada intaad na hanuunisay ka dib, nagana sii naxariistaada. illeen adaa wax siin.", "Ku samirka hanuunka.", "Duco ku ah joogitaanka iimaanka."),
        "dua_ya_muqallib" to DuaText("Wadnahayow", "Quluubta rogrog, qalbigayga ku adkee diintaada.", "Nebigu ﷺ ayaa inta badan sameeyay ducadan.", "Sida laga soo xigtay Umm Salamah (RA), ducada Nebigu ﷺ uu sameeyay inta badan."),
        "dua_la_tuakhidhna" to DuaText("Aayadaha ugu dambeeya ee suuradda Al-Baqarah", "Eebbow ha ina qaban haddaynu illowno ama gafno. Eebow ha na saarin culaab la mid ah tii aad kuwii naga horreeyey dusha saartay. Eebow ha nagu culaysin wax aynaan xamili karin. Na cafi, na cafi oo noo naxariiso. adaa gargaarahanaga ah ee naga caawi qoomka gaalada ah.", "Habeenkii hurdada ka hor - labada aayadood ee u dambeeya suuradda al-Baqarah.", "Qofkii akhriya labada aayadood ee u dambeeya suuradda al-Baqarah habeenkii way ku filan yihiin."),
        "dua_visiting_sick" to DuaText("Booqashada Bukaanka", "Waxaan Alle ka baryayaa inuu ku caafiyo Rabbigii Carshiga Wayn.", "Todoba jeer marka la booqanayo bukaanka.", "Hadday geeridu iman wayday, Alle wuu daawayn doonaa."),
        "dua_ruqyah_pain" to DuaText("Xanuunka Jirka", "Waxaan ka magan galay Allaah iyo xooggiisa xumaanta waxa aan dareemayo iyo waxa aan ka cabsanayo.", "Gacantaada dhig meesha ay ku xanuunayso, saddex jeer ku dheh Bismillah, dabadeed ducadan todoba jeer.", "Nebigu ﷺ wuxuu baray Cuthmaan bin Abil-Caas (RA) xanuun."),
        "dua_ruqyah_nabawi" to DuaText("Ruqyah nabiga ee buka", "Allahayow, Eebbaha Aadamaha! Dhibka ka saar oo dawo sii, waayo, adigaa daaweeya; Daawayntaada mooyaane dawo ma leh, waana daawo aan jirro ka tagin.", "Inta uu gacanta ka gudbinayo qofka buka.", "Nebigu ﷺ waxa uu akhriyey tan mar uu booqday xubno buka oo qoyskiisa ka mid ah."),
        "dua_kalimat_tammat" to DuaText("Ku Raadinta Qaxooti Erayada Wanaagsan", "Waxaan ka magan galay hadalka Alle oo qumman xumaanta waxa uu abuuray.", "Markaad meel joogsato, ama fiidkii.", "Qofkii meel istaaga oo sidaas ku yidhaahda, waxba ka yeeli maayo ilaa uu ka tago."),
        "dua_evil_eye" to DuaText("Ilaalinta Carruurta (Isha Xun)", "Waxaan idinkaga magan gelayaa qawlka Eebbe ee qumman shaydaan kasta iyo makhluuq kasta oo sun ah, iyo il kasta oo xun.", "Nabigu ﷺ waxa uu ku dul akhriyay Hasan iyo Xuseen (RA).", "Duco sunno ah oo carruurta ka ilaalinaysa isha xumaanta iyo dhibka (hal cunug waxaad dhahdaa 'U'īdhuka')."),
        "dua_seeing_afflicted" to DuaText("Inaad Aragto Qof Maxkamad Ku Jira", "Mahad dhamaanteed waxay u sugnaatay Allaahii iga daayay wuxuu kugu imtixaamay, igana fadilay wax badan oo khalqigiisa ah.", "Markaad aragto qof maxkamad ku jira (amus naftaada u sheeg).", "Kii yidhaahda waa laga nabad galay maxkamadayntaas."),
        "dua_istikhara" to DuaText("Salaatul-Istikhara", "Allow kheyrka waxaan ku raadiyaa cilmigaaga, awoodaada ayaan ku raadiyaa, waxaana ku waydiisanayaa fadligaaga wayn. Adigu awood baad leedahay, aniguna ma lihi; Waad og tahay aniguna ma garanayo, adiguna waxaad tahay og yahay waxa maqan. Illahow, haddi aqoontaada ay arrinkan (maskaxda ku hayso) ay u wanaagsan tahay diintayda, noloshayda iyo aakhiraydaba, ii xukun, ii fudaydi oo igu barako. Haddise ogaanshahaaga arrinkani u xun yahay diintayda, noloshayda iyo aakhiradayda, iga leexi oo iga jeedso, iina xukmi wanaag meel kasta oo ay tahay, i raalli geli.", "Laba rakcadood oo salaad ikhtiyaari ah ka dib, si loo raadiyo waxa u wanaagsan arrinka bannaan.", "Nabigu ﷺ waxa uu saxaabada u baray istikhara arimaha oo dhan isagoo u baray suurad quraanka kariimka ah."),
    )
}
